SELECT COUNT(*) FROM icr01_class_tree
 WHERE icr01_class_tree_id = #{classTreeId}
   AND icr01_company_id    = #{companyId}

mapper.update:
UPDATE icr01_class_tree
   SET icr01_class_tree_cd = #{req.classTreeCode},
       icr01_class_tree_nm = #{req.classTreeName},
       icr01_seq           = #{req.seq}
 WHERE icr01_class_tree_id = #{classTreeId}
   AND icr01_company_id    = #{companyId}

UPDATE icr01_class_tree
   SET icr01_parent_tree_id = #{parentTreeId}
 WHERE icr01_class_tree_id  = #{classTreeId}
   AND icr01_company_id     = #{companyId}

mapper.delete:
DELETE FROM icr01_class_tree
 WHERE icr01_class_tree_id = #{classTreeId}
   AND icr01_company_id    = #{companyId}

mapper.select:
SELECT
FROM icr01_class_tree WHERE icr01_class_tree_id IN ( WITH RECURSIVE icr_tree_down( icr01_class_tree_id , icr01_parent_tree_id , icr01_class_tree_cd , depth , path , cycle ) AS ( SELECT a.icr01_class_tree_id , a.icr01_parent_tree_id , a.icr01_class_tree_cd , 0 , ARRAY[a.icr01_class_tree_cd::text] , false FROM icr01_class_tree a WHERE icr01_company_id = #{companyId} AND icr01_class_tree_id = #{classTreeId} UNION ALL SELECT a.icr01_class_tree_id , a.icr01_parent_tree_id , a.icr01_class_tree_cd , b.depth + 1 , array_append(b.path, a.icr01_class_tree_cd::text) , a.icr01_class_tree_cd = any(b.path) FROM icr01_class_tree a , icr_tree_down b WHERE a.icr01_parent_tree_id = b.icr01_class_tree_id AND a.icr01_company_id = #{companyId} AND not cycle ) SELECT a.icr01_class_tree_id FROM icr_tree_down a ) AND icr01_company_id = #{companyId} AND icr01_type_cd = #{typeCode}
AND CONCAT(icr01_class_tree_cd, icr01_class_tree_nm) LIKE #{searchText}
ORDER BY icr01_class_tree_cd

SELECT 

  FROM icr01_class_tree
 WHERE icr01_class_tree_id = #{classTreeId}
   AND icr01_company_id    = #{companyId}

mapper.delete:
DELETE FROM icr01_class_tree
 WHERE icr01_class_tree_id = #{classTreeId}
   AND icr01_company_id    = #{companyId}
   AND icr01_type_cd       = 'IT'

